-- Helpdesk tickets raised by staff (OS) or families (ERP portal).
create table core.tickets (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references core.organizations(id) on delete cascade,
  branch_id uuid,
  category_id uuid,
  product_key text references core.products(key),
  title text not null,
  description text,
  priority text not null default 'normal' check (priority in ('low','normal','high','urgent')),
  status text not null default 'open' check (status in ('open','assigned','in_progress','waiting','resolved','closed','reopened')),
  raised_by_user_id uuid default app.uid(),
  raised_by_staff_id uuid,
  raised_by_name text,
  student_id uuid,
  owner_staff_id uuid,
  owner_role_key text,
  room_id uuid,
  location_text text,
  asset_tag text,
  parts jsonb,
  vendor text,
  vendor_ref uuid,
  cost numeric(12,2),
  due_at timestamptz,
  resolved_at timestamptz,
  closed_at timestamptz,
  resolution text,
  rating smallint check (rating is null or rating between 1 and 5),
  rating_comment text,
  source text not null default 'manual' check (source in ('manual','checklist','qr','portal')),
  photo_file_id uuid,
  voice_file_id uuid,
  payload jsonb not null default '{}',
  linked_type text,
  linked_id uuid,
  approval_request_id uuid,
  created_at timestamptz not null default now(),
  created_by uuid default app.uid(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (org_id, id),
  foreign key (org_id, branch_id) references core.branches(org_id, id),
  foreign key (org_id, category_id) references core.ticket_categories(org_id, id),
  foreign key (org_id, raised_by_staff_id) references core.staff(org_id, id),
  foreign key (org_id, student_id) references core.students(org_id, id),
  foreign key (org_id, owner_staff_id) references core.staff(org_id, id),
  foreign key (org_id, room_id) references core.rooms(org_id, id),
  foreign key (org_id, photo_file_id) references core.files(org_id, id),
  foreign key (org_id, voice_file_id) references core.files(org_id, id),
  foreign key (org_id, approval_request_id) references core.approval_requests(org_id, id)
);
create index tickets_branch on core.tickets(org_id, branch_id);
create index tickets_category_id on core.tickets(org_id, category_id);
create index tickets_raised_by_staff_id on core.tickets(org_id, raised_by_staff_id);
