-- internal rows are never shown to families.
create table core.ticket_events (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references core.organizations(id) on delete cascade,
  ticket_id uuid not null,
  actor_user_id uuid default app.uid(),
  actor_staff_id uuid,
  actor_name text,
  event text not null,
  from_status text,
  to_status text,
  note text,
  internal boolean not null default false,
  created_at timestamptz not null default now(),
  created_by uuid default app.uid(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (org_id, id),
  foreign key (org_id, ticket_id) references core.tickets(org_id, id) on delete cascade,
  foreign key (org_id, actor_staff_id) references core.staff(org_id, id)
);
create index ticket_events_ticket_id on core.ticket_events(org_id, ticket_id);
create index ticket_events_actor_staff_id on core.ticket_events(org_id, actor_staff_id);
create trigger trg_touch before update on core.ticket_events for each row execute function app.touch_updated_at();
grant select, insert, update, delete on core.ticket_events to authenticated, crm_server, os_server, erp_server;
grant select on core.ticket_events to platform_admin_server;
select app.apply_core_rls('ticket_events', 'permission', '*', 'helpdesk', 'not internal and exists (select 1 from core.tickets t where t.org_id = ticket_events.org_id and t.id = ticket_events.ticket_id)', null);
create policy ins_self on core.ticket_events for insert with check (
  org_id = app.current_org_id() and app.user_has_any_product(org_id) and actor_user_id = app.uid() and not internal
  and exists (select 1 from core.tickets t where t.org_id = ticket_events.org_id and t.id = ticket_events.ticket_id));

