  unique (org_id, id),
  foreign key (org_id, guardian_id) references core.guardians(org_id, id) on delete cascade,
  foreign key (org_id, student_id) references core.students(org_id, id) on delete cascade,
  foreign key (org_id, staff_id) references core.staff(org_id, id) on delete cascade,
  check ((subject_type = 'guardian') = (guardian_id is not null) and (subject_type = 'student') = (student_id is not null)
    and (subject_type = 'staff') = (staff_id is not null) and (subject_type = 'crm_guardian') = (crm_contact_id is not null))
);
create index consents_guardian_id on core.consents(org_id, guardian_id);
create index consents_student_id on core.consents(org_id, student_id);
create index consents_staff_id on core.consents(org_id, staff_id);
create trigger trg_touch before update on core.consents for each row execute function app.touch_updated_at();
grant select, insert, update, delete on core.consents to authenticated, crm_server, os_server, erp_server;
grant select on core.consents to platform_admin_server;
select app.apply_core_rls('consents', 'permission', '*', 'compliance', 'student_id = any(app.my_learner_ids()) or guardian_id in (select g.id from core.guardians g where g.org_id = consents.org_id and g.household_id = any(app.my_household_ids()))', 'subject_type <> ''crm_guardian'' or app.user_has_product(org_id, ''crm'')');

create table core.data_requests (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references core.organizations(id) on delete cascade,
  type text not null check (type in ('access','correction','erasure','export')),
  subject_type text,
  subject_id uuid,
  subject text,
  details text,
  status text not null default 'open' check (status in ('open','in_progress','done','rejected')),
  due_date date,
  evidence jsonb not null default '{}',
  requested_by_user_id uuid default app.uid(),
  product_key text references core.products(key),
  created_at timestamptz not null default now(),
  created_by uuid default app.uid(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (org_id, id)
);
create trigger trg_touch before update on core.data_requests for each row execute function app.touch_updated_at();
grant select, insert, update, delete on core.data_requests to authenticated, crm_server, os_server, erp_server;
grant select on core.data_requests to platform_admin_server;
select app.apply_core_rls('data_requests', 'permission', '*', 'compliance', 'requested_by_user_id = app.uid()', null);
create policy ins_self on core.data_requests for insert with check (
  org_id = app.current_org_id() and app.user_has_any_product(org_id) and requested_by_user_id = app.uid() and status = 'open');

create table core.retention_rules (
  id uuid primary key default gen_random_uuid(),
  org_id uuid not null references core.organizations(id) on delete cascade,
  data_type text not null,
  keep_years integer not null check (keep_years >= 0),
  action text not null default 'anonymise' check (action in ('anonymise','delete')),
  notes text,
  product_key text references core.products(key),
  created_at timestamptz not null default now(),
  created_by uuid default app.uid(),
  updated_at timestamptz not null default now(),
  deleted_at timestamptz,
  unique (org_id, id),
  unique nulls not distinct (org_id, data_type, product_key)
);
create trigger trg_touch before update on core.retention_rules for each row execute function app.touch_updated_at();
grant select, insert, update, delete on core.retention_rules to authenticated, crm_server, os_server, erp_server;
grant select on core.retention_rules to platform_admin_server;
select app.apply_core_rls('retention_rules', 'permission', '*', 'compliance', null, null);
